<?php require dirname(__DIR__).'/core/bootstrap.php';$u=auth(true);$admin=true;if(is_post()){verify_csrf();$id=(int)($_POST['id']??0);$status=input('status',20);if(in_array($status,['new','contacted','closed'],true)){run('UPDATE leads SET status=? WHERE id=?',[$status,$id]);audit('orcamento_atualizado','Briefing #'.$id);}flash('Atendimento atualizado.');go('admin/leads.php');}require ROOT.'/includes/panel.php';?><h1>Orçamentos recebidos.</h1><?php foreach(rows('SELECT * FROM leads ORDER BY id DESC LIMIT 200') as $l):?><article class="card"><h3>#<?=$l['id']?> <?=e($l['server_name'])?></h3><p><?=e($l['name'].' / '.$l['email'])?><br><?=e($l['plan'].' • '.$l['version'])?></p><p><?=e($l['body'])?></p><form method="post"><?php csrf();?><input type="hidden" name="id" value="<?=$l['id']?>"><div class="actions-row"><label>Status<select name="status"><?php foreach(['new'=>'Novo','contacted'=>'Contato realizado','closed'=>'Concluído'] as $k=>$v):?><option value="<?=$k?>" <?=$l['status']===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><button class="outline">Salvar status</button></div></form></article><?php endforeach;require ROOT.'/includes/endpanel.php';?>
